-- PxtlCa.BigVariant.Core 0.2.6599.36044, MIT licensed.
-- Source: https://github.com/Pxtl/BigVariant/tree/5418c78b2528e400e8bcd8a9d9b9bfd9173547a9
-- The assembly bytes are embedded so the integration containers need no custom image or network access.

USE [master];
GO

EXEC sp_configure 'clr enabled', 1;
RECONFIGURE;
GO

DECLARE @BigVariantHash varbinary(64) =
    0xE9664C6EFBD363CCBF348EA474920C80E739DCE1053D2D416E271036F16568AD26C7386D61B42A799170A94B90DAB4FF2C0B4F0A9553859729E8BD9C893454D6;

IF NOT EXISTS (
    SELECT 1
    FROM sys.trusted_assemblies
    WHERE hash = @BigVariantHash
)
BEGIN
    EXEC sys.sp_add_trusted_assembly
        @hash = @BigVariantHash,
        @description = N'PxtlCa.BigVariant.Core 0.2.6599.36044';
END;
GO

USE [model];
GO

IF NOT EXISTS (
    SELECT 1
    FROM sys.assemblies
    WHERE name = N'PxtlCa.BigVariant.Core'
)
BEGIN
    CREATE ASSEMBLY [PxtlCa.BigVariant.Core]
        AUTHORIZATION [dbo]
        FROM 
        WITH PERMISSION_SET = SAFE;
END;
GO

IF TYPE_ID(N'dbo.BigVariant') IS NULL
BEGIN
    EXEC(N'
        CREATE TYPE [dbo].[BigVariant]
        EXTERNAL NAME [PxtlCa.BigVariant.Core].[PxtlCa.BigVariant.Core.BigVariant];
    ');
END;
GO

IF OBJECT_ID(N'dbo.BigVariantFromBinary', N'FS') IS NULL
BEGIN
    EXEC(N'
        CREATE FUNCTION [dbo].[BigVariantFromBinary](@value varbinary(max))
        RETURNS [dbo].[BigVariant]
        AS EXTERNAL NAME
            [PxtlCa.BigVariant.Core].[PxtlCa.BigVariant.Core.UserDefinedFunctions].[BigVariantFromBinary];
    ');
END;
GO

IF OBJECT_ID(N'dbo.BigVariantFromDateTime2', N'FS') IS NULL
BEGIN
    EXEC(N'
        CREATE FUNCTION [dbo].[BigVariantFromDateTime2](@value datetime2)
        RETURNS [dbo].[BigVariant] WITH EXECUTE AS CALLER
        AS EXTERNAL NAME
            [PxtlCa.BigVariant.Core].[PxtlCa.BigVariant.Core.UserDefinedFunctions].[BigVariantFromDateTime2];
    ');
END;
GO

IF OBJECT_ID(N'dbo.BigVariantFromString', N'FS') IS NULL
BEGIN
    EXEC(N'
        CREATE FUNCTION [dbo].[BigVariantFromString](@value nvarchar(max))
        RETURNS [dbo].[BigVariant]
        AS EXTERNAL NAME
            [PxtlCa.BigVariant.Core].[PxtlCa.BigVariant.Core.UserDefinedFunctions].[BigVariantFromString];
    ');
END;
GO

IF OBJECT_ID(N'dbo.BigVariantFromVariant', N'FS') IS NULL
BEGIN
    EXEC(N'
        CREATE FUNCTION [dbo].[BigVariantFromVariant](@value sql_variant)
        RETURNS [dbo].[BigVariant]
        AS EXTERNAL NAME
            [PxtlCa.BigVariant.Core].[PxtlCa.BigVariant.Core.UserDefinedFunctions].[BigVariantFromVariant];
    ');
END;
GO

IF OBJECT_ID(N'dbo.BigVariantFromXml', N'FS') IS NULL
BEGIN
    EXEC(N'
        CREATE FUNCTION [dbo].[BigVariantFromXml](@value xml)
        RETURNS [dbo].[BigVariant]
        AS EXTERNAL NAME
            [PxtlCa.BigVariant.Core].[PxtlCa.BigVariant.Core.UserDefinedFunctions].[BigVariantFromXml];
    ');
END;
GO
